/// After CreateTable materialises a real Lance dataset on disk, ListTables on the root namespace must contain that table.
#[tokio::test(flavor = "multi_thread")]
async fn list_tables_after_create_contains_table() {
    let (caps, mut fixtures) = set_up().await;

    // ─── given ──────────────────────────────────
    fixtures.create_table_empty(vec!["TblA".to_string()]).await;

    // ─── when ───────────────────────────────────────────────
    {
        let request: ListTablesRequest = ListTablesRequest {
            id: Some(vec![]),
            ..Default::default()
        };
        let _resp = fixtures.api().list_tables(request).await;
        assert_contract_ok(&_resp);
        let _resp = _resp.expect("response_assertions require Ok response");
        assert!(
            _resp.tables.iter().any(|n| n == &"TblA".to_string()),
            "expected tables list {:?} to contain {:?}",
            _resp.tables,
            "TblA"
        );
    }

    fixtures.tear_down().await;
}

